def doc(lines, cap, crossed=False, W=560, H=200):
    """Specimen document drawn as SVG; lines = [(x, y, text, size, weight, anchor)] — text kept in English as printed."""
    body = f'<rect x="20" y="12" width="{W - 40}" height="{H - 50}" fill="#fffef7" stroke="#1e293b" stroke-width="2"/>'
    if crossed:
        body += '<line x1="40" y1="70" x2="90" y2="14" stroke="#1e293b" stroke-width="2"/><line x1="58" y1="70" x2="108" y2="14" stroke="#1e293b" stroke-width="2"/>'
    for x, y, s, sz, w, a in lines:
        body += T(x, y, s, sz, w, a)
    return svg(W, H, body, cap)


